import {FT,project,unproject,distance} from './geometry.mjs';
import {getWalls,validateOpening} from './walls.mjs';
export function setupWallClickTools({getState,checkpoint,render,showDialog,map,setView,setTool}){
 const wrap=document.createElement('div');wrap.className='wall-click-tools';wrap.innerHTML='<p class="source">Click a wall in Plan or 3D to add a door or window.</p><div class="two"><button id="drawWallPlan">Draw wall · Plan</button><button id="extendWallClick">Attach wall</button></div><div class="two"><button id="placeDoorClick">Place door</button><button id="placeWindowClick">Place window</button></div><button id="cancelWallClick" class="full">Cancel wall tool</button><p id="wallClickHint" class="source" role="status"></p>';document.querySelector('#wallEditor').parentElement.after(wrap);
 const $=id=>document.getElementById(id),preview=L.layerGroup().addTo(map);let start=null;
 const hint=message=>$('wallClickHint').textContent=message;
 const cancel=()=>{start=null;preview.clearLayers();document.body.dataset.wallTool='';hint('Click any wall to add an opening.')};
 for(const id of ['draw','pan','autoOutline','open','wallEditor','buildHouse','addPart'])$(id)?.addEventListener('click',cancel);$('cancelWallClick').onclick=cancel;document.addEventListener('keydown',e=>{if(e.key==='Escape')cancel()});
 for(const [id,mode]of [['placeDoorClick','Door'],['placeWindowClick','Window'],['extendWallClick','attach']])$(id).onclick=()=>{cancel();setTool('pan');document.body.dataset.wallTool=mode;hint(mode==='attach'?'Click an existing wall near the endpoint where the new wall should start.':'Click a wall where the '+mode.toLowerCase()+' should go.')};
 $('drawWallPlan').onclick=()=>{cancel();setTool('pan');setView('plan');document.body.dataset.wallTool='draw-wall';hint('Click the start, then the end of the new wall. Escape cancels.')};
 const snap=geo=>{const p=map.latLngToContainerPoint([geo.lat,geo.lng]);let best=14,result=geo;for(const wall of getWalls(getState()))for(const q of [wall.a,wall.b]){const g=unproject(q,getState().origin),d=p.distanceTo(map.latLngToContainerPoint([g.lat,g.lng]));if(d<best){best=d;result=g}}return result};
 map.on('mousemove',e=>{if(start&&document.body.dataset.wallTool==='draw-wall'){preview.clearLayers();L.polyline([start,snap(e.latlng)],{color:'#edc383',dashArray:'6 6',interactive:false}).addTo(preview)}});
 document.addEventListener('wall-plan-point',e=>{const p=snap(e.detail);if(!start){start=p;hint('Now click the wall endpoint.');return}const a=project(start,getState().origin),b=project(p,getState().origin);if(distance(a,b)<FT){hint('Wall must be at least 1 ft long.');return}const length=distance(a,b)/FT,angle=Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI;cancel();wallDialog(a,length,angle)});
 const input=(id,label,value)=>'<label>'+label+'<input id="'+id+'" type="number" step="0.125" value="'+value+'"></label>';
 function wallDialog(a,length=20,angle=0){showDialog('Add wall here','<p class="source">The start is fixed at the selected point. Adjust the measured length, direction, and wall height.</p><div class="form-grid">'+input('clickWallLength','Length (ft)',length.toFixed(3))+input('clickWallAngle','Direction (degrees; 0 east, 90 north)',angle.toFixed(3))+input('clickWallHeight','Height (ft)',10)+'</div><button id="confirmClickWall" class="primary full">Add wall</button><p id="clickWallMessage" role="status"></p>');$('confirmClickWall').onclick=()=>{const length=+$('clickWallLength').value,angle=+$('clickWallAngle').value*Math.PI/180,height=+$('clickWallHeight').value;if(![length,angle,height].every(Number.isFinite)||length<1||length>500||height<1||height>200){$('clickWallMessage').textContent='Use length 1–500 ft and height 1–200 ft.';return}const state=getState();if((state.walls||[]).length>=100){$('clickWallMessage').textContent='Maximum 100 standalone walls.';return}checkpoint();(state.walls||=[]).push({id:crypto.randomUUID(),name:'Wall '+((state.walls?.length||0)+1),a:unproject(a,state.origin),b:unproject({x:a.x+length*FT*Math.cos(angle),y:a.y+length*FT*Math.sin(angle)},state.origin),height});render();$('dialog').close();hint('Wall added. Click a wall to add an opening.')} }
 document.addEventListener('wall-picked',event=>{const wall=getWalls(getState()).find(w=>w.id===event.detail.wallId);if(!wall)return;const mode=document.body.dataset.wallTool;if(mode==='draw-wall'){document.dispatchEvent(new CustomEvent('wall-plan-point',{detail:unproject({x:wall.a.x+(wall.b.x-wall.a.x)*Math.max(0,Math.min(1,(event.detail.offset||0)/wall.widthFeet)),y:wall.a.y+(wall.b.y-wall.a.y)*Math.max(0,Math.min(1,(event.detail.offset||0)/wall.widthFeet))},getState().origin)}));return}const offset=Math.max(0,Math.min(wall.widthFeet,event.detail.offset||0));if(mode==='attach'){cancel();wallDialog(offset<wall.widthFeet/2?wall.a:wall.b);return}const kind=mode==='Window'?'Window':'Door',width=Math.min(3,wall.widthFeet),height=Math.min(kind==='Window'?4:7,wall.height),sill=kind==='Window'?Math.min(3,wall.height-height):0;
 showDialog('Place '+kind.toLowerCase(),'<p id="pickedWallName" class="source"></p><label>Opening type<select id="clickOpeningKind"><option>Door</option><option>Window</option></select></label><div class="form-grid">'+input('clickOpeningOffset','From wall start (ft)',Math.max(0,Math.min(wall.widthFeet-width,offset-width/2)).toFixed(3))+input('clickOpeningWidth','Width (ft)',width)+input('clickOpeningHeight','Height (ft)',height)+input('clickOpeningSill','Bottom above floor (ft)',sill)+'</div><button id="confirmClickOpening" class="primary full">Add opening here</button><p id="clickOpeningMessage" role="status"></p>');$('pickedWallName').textContent=wall.name+' · '+wall.widthFeet.toFixed(2)+' ft long × '+wall.height+' ft high';$('clickOpeningKind').value=kind;
 $('confirmClickOpening').onclick=()=>{try{const state=getState();if((state.wallOpenings||[]).length>=200)throw Error('Maximum 200 openings.');const opening={id:crypto.randomUUID(),wallId:wall.id,kind:$('clickOpeningKind').value,offset:+$('clickOpeningOffset').value,width:+$('clickOpeningWidth').value,height:+$('clickOpeningHeight').value,sill:+$('clickOpeningSill').value};validateOpening(wall,opening,state.wallOpenings||[]);checkpoint();(state.wallOpenings||=[]).push(opening);render();$('dialog').close();hint(opening.kind+' added. Click another wall to continue.')}catch(error){$('clickOpeningMessage').textContent=error.message}};});
}
